pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4 constant IERC1155_ID = type(IERC1155).interfaceId;
    bytes4 constant IERC1155MetadataURI_ID = type(IERC1155MetadataURI).interfaceId;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed parameter is the interface id we query; the general rule:
    // reference C reports support for ERC1155-related ids and only those predefined ones
    // (we assert an implication: if c.supportsInterface(id) == true then id must be one of the ERC1155 ids)
    function testFuzz_property(bytes4 interfaceId) public {
        // keep domain wide; no assume that excludes target ids

        // call supportsInterface but catch reverts just in case (spec requires view but be defensive)
        bool ok;
        try c.supportsInterface(interfaceId) returns (bool supported) {
            ok = supported;
        } catch {
            // If it reverts, treat as not supported
            ok = false;
        }

        // General rule: if the contract reports it supports an interface id, it must be one of the two ERC1155 ids.
        // Reference C satisfies: supportsInterface(id) implies id==IERC1155_ID || id==IERC1155MetadataURI_ID
        // Mutant removes those disjuncts so it can return false for those ids; conversely the mutant may never
        // report support for those ids — causing some interfaceId (the ERC1155 ids) to violate the implication
        // when the mutant returns false but the reference would have returned true; our single assertion checks
        // the universal implication on c: if c says true, it must be one of the known ERC1155 ids.
        assertTrue(!ok || interfaceId == IERC1155_ID || interfaceId == IERC1155MetadataURI_ID);
    }
}

