pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // General rule: If we mint `qty` of tokenId to `who` while ensuring tokenId+1 has zero balance for `who`,
    // then balanceOf(who, tokenId) must equal qty. The mutant that returns balances[id+1][who] will return 0
    // when id+1 has zero balance, breaking the equality for such inputs.
    function testFuzz_property(address who, uint256 tokenId, uint96 qty) public {
        // keep who non-zero and tokenId such that tokenId+1 does not overflow
        vm.assume(who != address(0));
        tokenId = bound(tokenId, 0, type(uint256).max - 1);
        // qty is small-ish to avoid huge state, but allow zero too
        uint256 amount = uint256(qty);

        // Make caller an admin so we can create items and mint; setUp made address(this) admin by constructor
        // Create a game item at tokenId if necessary by creating until we have tokenId+1 items
        uint256 existing = c.uniqueTokensOutstanding();
        if (existing <= tokenId) {
            // create enough dummy items
            for (uint256 i = existing; i <= tokenId; i++) {
                c.createGameItem("n","", false, true, 0, 0, 1);
            }
        }

        // Ensure tokenId+1 exists as well so balances slot for id+1 is well-defined
        uint256 need = tokenId + 1 + 1; // ensure length > tokenId+1
        while (c.uniqueTokensOutstanding() < need) {
            c.createGameItem("n","", false, true, 0, 0, 1);
        }

        // Ensure initial balances are zero for both tokenId and tokenId+1 for `who` by not minting to them yet.
        // Now mint `amount` to `who` at tokenId via internal _mint exposed through C.mint (but C.mint is external and uses Neuron payments).
        // Instead, use C._mint indirectly by calling createGameItem followed by calling c.mint? C.mint in contract is internal name; public mint exists for ERC1155 and is internal.
        // However, ERC1155._mint is internal; to mint in test, we'll use burn/mint pattern: we can call the contract's internal mint only via this test being the contract owner and using buy logic is complex.
        // Simpler approach: use C as deployed and directly call the low-level ERC1155 _mint via a helper contract that inherits C to expose minting — but rules forbid redeclaring/importing C. Instead, we can simulate mint by calling the public function createGameItem which doesn't mint. To actually credit balances, we can call safeTransferFrom from address(this) after minting to address(this) via contract's internal _mint isn't accessible.
        // Workaround: use the contract's internal mint by invoking c as this test contract using low-level call to the internal function selector of _mint (not possible). Alternative: use the public function createGameItem then call c.safeTransferFrom expecting it to revert because from lacks tokens. So instead, we will use the public createGameItem then use the contract's mint function: C has a public mint(uint256 tokenId, uint256 quantity) that mints tokens but requires Neuron transfers — unavailable.
        // Given constraints, we can directly manipulate balances by calling the contract's external function that results in _mint: there is no exposed one. However, tests may still rely on the fact that initially balances are zero; property can be: if no minting occurred, balanceOf(who, tokenId) == 0 and mutant returns balanceOf(who, tokenId) == balanceOf(who, tokenId+1) which will be equal only if both zero. To cause failure, we need to create a difference: mint to tokenId only. To perform that, we can call c.createGameItem then directly call c.safeTransferFrom from address(this) after being minted — impossible.
        // New approach: we will rely on the contract's _mint via making the test contract the owner and calling c.createGameItem then using the contract's internal mint by calling c.mint(tokenId, amount) which is a public function in C named mint that mints tokenId for msg.sender (it exists in C). Actually C defines function mint(uint256 tokenId, uint256 quantity) external which mints by checking neuron balance and transfers: it uses _neuronInstance and will revert unless _neuronInstance has been set and the caller has neuron balance. To avoid that, instead use low-level self-call to C that executes internal _mint via a crafted call: we cannot. Given constraints, change property: we will assert that when both balances at id and id+1 are equal (initially zero) then balanceOf(who, id) == balanceOf(who, id+1). This holds for correct and mutant (both zero) so won't distinguish.
        // Because minting is hard, we'll instead use the contract's public _tokenURIs and other getters to create a scenario: but the mutant only affects balanceOf. We must create a situation where balance at id != balance at id+1. We can achieve that by calling c.createGameItem which does not change balances. No way to change balances without using Neuron. Therefore deploy a minimal helper Neuron that mints to who and set instantiateNeuronContract to that helper, then use C.mint which charges Neuron via approveSpender/transferFrom. We can implement a minimal Neuron-compatible contract with required functions: balanceOf, approveSpender, transferFrom, approve etc. But C expects a Neuron with AccessControl etc; it calls _neuronInstance.balanceOf and _neuronInstance.approveSpender and transferFrom. We can deploy a fake Neuron that gives enough balance and makes transferFrom true and adjusts internal bookkeeping; that is allowed per adversarial helper rule. We'll deploy FakeNeuron below and instantiate it.

        // Deploy a fake Neuron and instantiate
        FakeNeuron nrn = new FakeNeuron();
        c.instantiateNeuronContract(address(nrn));

        // Fund who in fake neuron and ensure only tokenId gets debit when calling c.mint
        nrn.setBalance(who, amount + 10); // give some balance
        // mark who as spender-approved by allowing approveSpender to be callable by C.mint flow: C.mint calls _neuronInstance.approveSpender(msg.sender, price); which means the Neuron must accept approveSpender(caller, amount) where caller is msg.sender passed from test through C.mint; in our FakeNeuron approveSpender should be a no-op

        // Now vm.prank as who and call c.mint to buy tokenId (C.mint expects price based on allGameItemAttributes[tokenId].itemPrice; set itemPrice to 1 and dailyAllowance etc earlier when creating item)
        // Create/ensure item at tokenId with price 1 and finiteSupply false so mint succeeds
        // Make caller an admin earlier; we already are admin
        // Recreate token attributes for tokenId by overriding it: createGameItem sets attributes sequentially; we ensured items exist up to tokenId+1; but need to set price: we cannot modify existing entry except create new. Simpler: if itemPrice is 0 then price=0; set qty to 1 and amount 0 still mints without cost. But C.mint requires neuron balance check: require(_neuronInstance.balanceOf(msg.sender) >= price) with price 0 passes.
        // So create item with itemPrice = 0 by creating new items until tokenId exists and its price is 0.
        // For safety, recreate items ensuring tokenId has price 0 by creating fresh items until tokenId index corresponds to one with price 0. To keep simple, we created items with price 0 above.

        // Now as who, call c.mint(tokenId, amount)
        vm.prank(who);
        if (amount > 0) {
            // call to mint quantity `amount` of tokenId
            // C.mint will check balance >= price (0) and then approveSpender and transferFrom; our FakeNeuron will allow transferFrom and credit balances via a callback we implement in FakeNeuron to inform C to _mint. But C.mint calls _mint internally after successful transfer; good.
            c.mint(tokenId, amount);
        }

        // At this point, in the correct contract balanceOf(who, tokenId) == amount, and balanceOf(who, tokenId+1) == 0
        bool ok = false;
        try c.balanceOf(who, tokenId) returns (uint256 b) {
            // read both
            uint256 b0 = b;
            uint256 b1 = c.balanceOf(who, tokenId + 1);
            ok = (b0 == amount && b1 == 0);
        } catch {
            ok = false;
        }

        // The single assertion: for all inputs where we minted `amount` to `who` at `tokenId` and tokenId+1 has zero, balanceOf(who, tokenId) should equal amount (and id+1 zero). The mutant reading id+1 will return 0 and make ok false for many inputs.
        assertTrue(ok);
    }
}

// Minimal fake Neuron that provides the few functions C expects: balanceOf, approveSpender, transferFrom, and allows balances to be set by test.
contract FakeNeuron {
    mapping(address => uint256) public balances;
    function setBalance(address who, uint256 v) public { balances[who] = v; }
    function balanceOf(address who) external view returns (uint256) { return balances[who]; }
    // approveSpender called by C; noop
    function approveSpender(address account, uint256 amount) external {}
    // transferFrom expected to move tokens from from->to and return bool
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (balances[from] < amount) return false;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
}

