        vm.assume(to != address(0));
        // bound tokenId and quantity to reasonable ranges so the fuzzer explores useful cases
        tokenId = bound(tokenId, 0, 10);
        quantity = bound(quantity, 1, 100);

        // make caller an admin so we can create items and mint
        // set up an admin (this contract is already owner in constructor), create a game item and instantiate neuron not needed
        // create a game item so tokenId exists (createGameItem pushes sequentially starting at 0)
        string memory n = "item";
        string memory uri = "uri";
        bool finiteSupply = false;
        bool transferable = true;
        uint256 itemsRemaining = 1000;
        uint256 itemPrice = 1;
        uint16 dailyAllowance = 10;

        // ensure enough items exist to cover tokenId: create up to tokenId
        for (uint256 i = 0; i <= tokenId; i++) {
            c.createGameItem(n, uri, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);
        }

        // mint quantity of tokenId to `to` by calling internal mint via this contract's context: C.mint is public and mints tokenId
        // The contract's mint requires tokenId < _itemCount which is satisfied
        c.mint(tokenId, quantity);
        // The above mints to msg.sender (this test contract). We need balanceOf for `to`, so transfer from this to `to` if to != address(this)
        if (to != address(this)) {
