// Minimal mock implementing just enough of Neuron used by C.mint
contract MockNeuron {
    mapping(address => uint256) public balances;
    mapping(address => mapping(address => uint256)) public allowances;

    function setBalance(address who, uint256 amt) external {
        balances[who] = amt;
    }

    function balanceOf(address account) external view returns (uint256) {
        return balances[account];
    }

    // C calls approveSpender(msg.sender, price) on Neuron
    function approveSpender(address account, uint256 amount) external {
        // set allowance from account to msg.sender (the C contract) so transferFrom can succeed
        allowances[account][msg.sender] = amount;
    }

    // transferFrom(from, to, price) called by C
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (balances[from] < amount) return false;
        uint256 allowed = allowances[from][msg.sender];
        if (allowed < amount) return false;
        balances[from] -= amount;
        balances[to] += amount;
        allowances[from][msg.sender] = allowed - amount;
        return true;
    }
}

